let _markdown = "\n\nimport { UrlBar } from './tabs.client';\n\n<Installation name=\"tabs\" />\n\nUsage [#usage]\n\n<FeedbackBlock id=\"bda05426503bbb4a\" body=\"Add MDX components.\">\n  Add MDX components.\n</FeedbackBlock>\n\n```tsx title=\"mdx-components.tsx\"\nimport defaultMdxComponents from 'fumadocs-ui/mdx';\nimport * as TabsComponents from 'fumadocs-ui/components/tabs';\nimport type { MDXComponents } from 'mdx/types';\n\nexport function getMDXComponents(components?: MDXComponents): MDXComponents {\n  return {\n    ...defaultMdxComponents,\n    ...TabsComponents, // [!code ++]\n    ...components,\n  };\n}\n```\n\n<FeedbackBlock id=\"0e76a830c3efd958\" body=\"And use it in your MDX content:\">\n  And use it in your MDX content:\n</FeedbackBlock>\n\n```mdx title=\"content.mdx\"\n<Tabs items={['Javascript', 'Rust']}>\n  <Tab value=\"Javascript\">Javascript is weird</Tab>\n  <Tab value=\"Rust\">Rust is fast</Tab>\n</Tabs>\n```\n\n<Tabs items={['Javascript', 'Rust']}>\n  <Tab value=\"Javascript\">\n    Javascript is weird\n  </Tab>\n\n  <Tab value=\"Rust\">\n    Rust is fast\n  </Tab>\n</Tabs>\n\nWithout value [#without-value]\n\n<FeedbackBlock id=\"d5007f1788e0b9a9\" body=\"Without a value, it detects from the children index. Note that it might cause errors on re-renders, it's not encouraged if the tabs might change.\">\n  Without a `value`, it detects from the children index. Note that it might cause errors on re-renders, it's not encouraged if the tabs might change.\n</FeedbackBlock>\n\n```mdx\nimport { Tab, Tabs } from 'fumadocs-ui/components/tabs';\n\n<Tabs items={['Javascript', 'Rust']}>\n  <Tab>Javascript is weird</Tab>\n  <Tab>Rust is fast</Tab>\n</Tabs>\n```\n\n<Tabs items={['Javascript', 'Rust']}>\n  <Tab>\n    Javascript is weird\n  </Tab>\n\n  <Tab>\n    Rust is fast\n  </Tab>\n</Tabs>\n\nShared Value [#shared-value]\n\n<FeedbackBlock\n  id=\"6d00c949c8fcd05d\"\n  body=\"By passing an groupId property, you can share a value across all tabs with the same\nid.\"\n>\n  By passing an `groupId` property, you can share a value across all tabs with the same\n  id.\n</FeedbackBlock>\n\n```mdx\n<Tabs groupId=\"language\" items={['Javascript', 'Rust']}>\n  <Tab value=\"Javascript\">Javascript is weird</Tab>\n  <Tab value=\"Rust\">Rust is fast</Tab>\n</Tabs>\n```\n\nPersistent [#persistent]\n\n<FeedbackBlock id=\"3b9aa470179c0195\" body=\"When groupId is specified, their value will be temporarily stored in sessionStorage.\">\n  When `groupId` is specified, their value will be temporarily stored in `sessionStorage`.\n</FeedbackBlock>\n\n<FeedbackBlock\n  id=\"8029329c4c8b5bd6\"\n  body=\"To persist the value, you can specify a persist prop. The value will be\nstored in localStorage, with its group ID as storage key.\"\n>\n  To persist the value, you can specify a `persist` prop. The value will be\n  stored in `localStorage`, with its group ID as storage key.\n</FeedbackBlock>\n\n```mdx\n<Tabs groupId=\"language\" items={['Javascript', 'Rust']} persist>\n  <Tab value=\"Javascript\">Javascript is weird</Tab>\n  <Tab value=\"Rust\">Rust is fast</Tab>\n</Tabs>\n```\n\nDefault Value [#default-value]\n\n<FeedbackBlock id=\"818c611486eb16f4\" body=\"Set a default value by passing defaultIndex.\">\n  Set a default value by passing `defaultIndex`.\n</FeedbackBlock>\n\n```mdx\n<Tabs items={['Javascript', 'Rust']} defaultIndex={1}>\n  <Tab value=\"Javascript\">Javascript is weird</Tab>\n  <Tab value=\"Rust\">Rust is fast</Tab>\n</Tabs>\n```\n\nLink to Tab [#link-to-tab]\n\n<FeedbackBlock id=\"c677465d6942d320\" body=\"Use HTML id attribute to link to a specific tab.\">\n  Use HTML `id` attribute to link to a specific tab.\n</FeedbackBlock>\n\n```mdx\n<Tabs items={['Javascript', 'Rust', 'C++']}>\n  <Tab value=\"Javascript\">Javascript is weird</Tab>\n  <Tab value=\"Rust\">Rust is fast</Tab>\n  <Tab id=\"tab-cpp\" value=\"C++\">\n    `Hello World`\n  </Tab>\n</Tabs>\n```\n\n<FeedbackBlock id=\"e9bd44965b47df87\" body=\"You can add the hash #tab-cpp to your URL and reload, the C++ tab will be activated.\">\n  You can add the hash `#tab-cpp` to your URL and reload, the C++ tab will be activated.\n</FeedbackBlock>\n\n<Tabs items={['Javascript', 'Rust', 'C++']}>\n  <Tab value=\"Javascript\">\n    Javascript is weird\n  </Tab>\n\n  <Tab value=\"Rust\">\n    Rust is fast\n  </Tab>\n\n  <Tab id=\"tab-cpp\" value=\"C++\">\n    `Hello World`\n  </Tab>\n</Tabs>\n\n<FeedbackBlock\n  id=\"3fe7cfce25f58c9a\"\n  body=\"Additionally, the updateAnchor property can be set to true in the Tabs component\nto automatically update the URL hash whenever time a new tab is selected:\"\n>\n  Additionally, the `updateAnchor` property can be set to `true` in the `Tabs` component\n  to automatically update the URL hash whenever time a new tab is selected:\n</FeedbackBlock>\n\n```mdx\n<Tabs items={['Javascript', 'Rust', 'C++']} updateAnchor>\n  <Tab id=\"tab-js\" value=\"Javascript\">\n    Javascript is weird\n  </Tab>\n  <Tab id=\"tab-rs\" value=\"Rust\">\n    Rust is fast\n  </Tab>\n  <Tab id=\"tab-cpp\" value=\"C++\">\n    `Hello World`\n  </Tab>\n</Tabs>\n```\n\n<UrlBar />\n\n<Tabs items={['Hello', 'World']} updateAnchor>\n  <Tab id=\"tab-hello\" value=\"Hello\">\n    Hello!\n  </Tab>\n\n  <Tab id=\"tab-world\" value=\"World\">\n    World!\n  </Tab>\n</Tabs>\n\nAdvanced Usage [#advanced-usage]\n\n<FeedbackBlock id=\"d850c9b8b88ef2f8\" body=\"Use it in the primitive way:\">\n  Use it in the primitive way:\n</FeedbackBlock>\n\n```mdx\n<Tabs defaultValue=\"npm\">\n  <TabsList>\n    <TabsTrigger value=\"npm\">\n      <NpmIcon />\n      npm\n    </TabsTrigger>\n  </TabsList>\n  <TabsContent value=\"npm\">Hello World</TabsContent>\n</Tabs>\n```\n\n<Tabs defaultValue=\"npm\">\n  <TabsList>\n    <TabsTrigger value=\"npm\">\n      <svg role=\"img\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\">\n        <title>\n          npm\n        </title>\n\n        <path fill=\"currentColor\" d=\"M1.763 0C.786 0 0 .786 0 1.763v20.474C0 23.214.786 24 1.763 24h20.474c.977 0 1.763-.786 1.763-1.763V1.763C24 .786 23.214 0 22.237 0zM5.13 5.323l13.837.019-.009 13.836h-3.464l.01-10.382h-3.456L12.04 19.17H5.113z\" />\n      </svg>\n\n      npm\n    </TabsTrigger>\n  </TabsList>\n\n  <TabsContent value=\"npm\">\n    Hello World\n  </TabsContent>\n</Tabs>\n";
